<?php
declare(strict_types=1);
function cat_categories():array{return ['website'=>'Сайты','landing'=>'Лендинги','webapp'=>'Веб-приложения','ai_agent'=>'ИИ-агенты','crm'=>'CRM-системы','automation'=>'Автоматизация бизнеса','integration'=>'Интеграции'];}
function cat_prod_type(string $category):string{return ['website'=>'website','landing'=>'website','webapp'=>'application','ai_agent'=>'agent_spec','crm'=>'application','automation'=>'integration','integration'=>'integration'][$category];}
function cat_key(mixed $s):string{if(!is_string($s)||!preg_match('/^[a-z][a-z0-9_]{0,30}$/D',$s)||in_array($s,['constructor','prototype'],true))crm_fail(422,'Проверьте технический идентификатор поля или пакета.');return $s;}
function cat_template(mixed $v):array{
 if(!is_array($v))crm_fail(422,'Нужна структура анкеты.');prod_exact($v,['title','steps']);cc_text($v,'title',190);if(!is_array($v['steps'])||!array_is_list($v['steps'])||!count($v['steps'])||count($v['steps'])>8)crm_fail(422,'В анкете должно быть 1–8 шагов.');$seen=[];$count=0;
 foreach($v['steps'] as $step){if(!is_array($step))crm_fail(422,'Проверьте шаг анкеты.');prod_exact($step,['title','questions']);cc_text($step,'title',190);if(!is_array($step['questions'])||!array_is_list($step['questions'])||!count($step['questions']))crm_fail(422,'В шаге нужны вопросы.');foreach($step['questions'] as $q){if(!is_array($q))crm_fail(422,'Проверьте вопрос.');prod_exact($q,['id','label','type','semantic','required','options','min','max','when']);$id=cat_key($q['id']);if(isset($seen[$id])||++$count>30)crm_fail(422,'Не более 30 разных вопросов.');cc_text($q,'label',190);if(!in_array($q['type'],['text','textarea','number','choice','multi','bool'],true)||!in_array($q['semantic'],['goal','functionality','integrations','design','deliverables','budget','deadline','other'],true)||!is_bool($q['required']))crm_fail(422,'Проверьте тип, назначение и обязательность вопроса.');
 if(!is_array($q['options'])||!array_is_list($q['options'])||count($q['options'])>20||count(array_unique($q['options'],SORT_REGULAR))!==count($q['options']))crm_fail(422,'Проверьте варианты ответа.');foreach($q['options'] as $option)if(!is_string($option)||trim($option)===''||mb_strlen($option)>150)crm_fail(422,'Некорректный вариант ответа.');if(in_array($q['type'],['choice','multi'],true)&&count($q['options'])<2)crm_fail(422,'Для выбора нужны минимум два варианта.');
 if(!is_int($q['min'])||!is_int($q['max'])||$q['min']<0||$q['min']>$q['max']||$q['max']>($q['type']==='number'?1000000:3000))crm_fail(422,'Проверьте границы ответа.');
 if($q['when']!==null){$w=$q['when'];if(!is_array($w))crm_fail(422,'Проверьте условие вопроса.');prod_exact($w,['field','equals']);if(!is_string($w['field'])||!isset($seen[$w['field']])||!(is_string($w['equals'])||is_int($w['equals'])||is_bool($w['equals'])))crm_fail(422,'Условие должно ссылаться на предыдущий вопрос и простое значение.');}$seen[$id]=true;}}
 return $v;
}
function cat_visible(array $q,array $answers):bool{if($q['when']===null)return true;$value=$answers[$q['when']['field']]??null;return is_array($value)?in_array($q['when']['equals'],$value,true):$value===$q['when']['equals'];}
function cat_answers(array $template,mixed $answers,bool $complete):array{
 if(!is_array($answers)||array_is_list($answers)&&$answers!==[])crm_fail(422,'Ответы должны быть объектом.');$out=[];$known=[];
 foreach($template['steps'] as $s)foreach($s['questions'] as $q){$id=$q['id'];$known[$id]=true;$value=$answers[$id]??null;if(!cat_visible($q,$out)){if($value!==null&&$value!==''&&$value!==[])crm_fail(422,'Скрытые ответы нужно очистить: '.$q['label']);continue;}
 $empty=$value===null||$value===''||$value===[];if($empty){if($complete&&$q['required'])crm_fail(422,'Заполните: '.$q['label']);continue;}
 $ok=match($q['type']){'number'=>is_int($value)&&$value>=$q['min']&&$value<=$q['max'],'bool'=>is_bool($value),'choice'=>is_string($value)&&in_array($value,$q['options'],true),'multi'=>is_array($value)&&array_is_list($value)&&count($value)<=20&&count(array_unique($value,SORT_REGULAR))===count($value)&&!array_filter($value,fn($v)=>!is_string($v)||!in_array($v,$q['options'],true)),default=>is_string($value)&&mb_check_encoding($value,'UTF-8')&&!str_contains($value,"\0")&&mb_strlen($value)>=$q['min']&&mb_strlen($value)<=$q['max']};if(!$ok)crm_fail(422,'Проверьте ответ: '.$q['label']);$out[$id]=$value;}
 if(array_diff(array_keys($answers),array_keys($known)))crm_fail(422,'Анкета содержит неизвестные поля.');if(strlen(ai_json($out))>20000)crm_fail(422,'Ответы слишком велики.');return $out;
}
function cat_service(mixed $v):array{
 if(!is_array($v))crm_fail(422,'Нужна структура услуги.');prod_exact($v,['name','description','category','scope','deliverables','pricing_type','packages','consultation_url']);cc_text($v,'name',190);cc_text($v,'description',4000);if(!isset(cat_categories()[$v['category']??''])||!in_array($v['pricing_type'],['estimate','fixed'],true))crm_fail(422,'Выберите категорию и способ оценки.');foreach(['scope','deliverables'] as $key){ai_schema_value($v[$key],'list');if(!count($v[$key]))crm_fail(422,'Заполните состав услуги и результаты.');}
 if(!is_string($v['consultation_url'])||!preg_match('~^https://t\.me/[A-Za-z0-9_]{5,32}$~D',$v['consultation_url']))crm_fail(422,'Укажите действительную ссылку Telegram для консультации.');if(!is_array($v['packages'])||!array_is_list($v['packages'])||!count($v['packages'])||count($v['packages'])>8)crm_fail(422,'Нужно 1–8 пакетов.');$seen=[];
 foreach($v['packages'] as $p){if(!is_array($p))crm_fail(422,'Проверьте пакет.');prod_exact($p,['id','name','description','price','work_packages','quantity_rules']);$id=cat_key($p['id']);if(isset($seen[$id]))crm_fail(422,'Пакеты должны иметь разные идентификаторы.');$seen[$id]=true;cc_text($p,'name',190);cc_text($p,'description',2000);if($p['price']!==null)bill_minor($p['price']);if($v['pricing_type']==='fixed'&&$p['price']===null)crm_fail(422,'Фиксированная цена должна быть явно задана владельцем.');pricing_packages($p['work_packages']);
 if(!is_array($p['quantity_rules'])||!array_is_list($p['quantity_rules'])||count($p['quantity_rules'])>20)crm_fail(422,'Проверьте правила объёмов.');foreach($p['quantity_rules'] as $r){if(!is_array($r))crm_fail(422,'Проверьте правило объёма.');prod_exact($r,['question','package_index','quantity']);cat_key($r['question']);if(!is_int($r['package_index'])||!isset($p['work_packages'][$r['package_index']])||!in_array($r['quantity'],['development_hours','testing_hours','ai_input_tokens','ai_output_tokens','hosting_months','tool_units','external_units','other_units'],true))crm_fail(422,'Неверное правило количества.');}}
 return $v;
}
